package com.lbos.commercecustomer.entity; import jakarta.persistence.*;import java.util.*;import java.time.*;import java.math.*;import com.lbos.commercecustomer.enums.CategoryStatus; @Entity @Table(name="product_categories") public class ProductCategory {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="category_id") private Long id; @Column(name="category_name",nullable=false,unique=true,length=100) private String name; @Column(length=500) private String description; @Enumerated(EnumType.STRING) @Column(name="status",nullable=false,length=15) private CategoryStatus status=CategoryStatus.ACTIVE; public ProductCategory(){} public Long getId(){return id;} public void setId(Long v){id=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public CategoryStatus getStatus(){return status;} public void setStatus(CategoryStatus v){status=v;}}